/* =========================================================
   مكتب السرحان للاستقدام — سندات الاستلام / التسليم
   app.js
   لا يوجد أي اتصال بالإنترنت أو خادم هنا: كل شيء يعمل محليًا
   داخل المتصفح فقط. لا تُحفظ أو تُرسل أي بيانات لأي مكان.
   ========================================================= */
(function () {
  'use strict';

  /* ---------------------------------------------------------
     1) التنقل بين نوعي السند (Tabs)
  --------------------------------------------------------- */
  var tabBtns = document.querySelectorAll('.tab-btn');
  var formSections = document.querySelectorAll('.form-section');

  tabBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      tabBtns.forEach(function (b) { b.classList.remove('active'); b.setAttribute('aria-selected', 'false'); });
      formSections.forEach(function (s) { s.classList.remove('active'); });
      btn.classList.add('active');
      btn.setAttribute('aria-selected', 'true');
      var target = document.getElementById(btn.dataset.target);
      if (target) target.classList.add('active');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  });

  /* ---------------------------------------------------------
     2) حقل "الجنسية: أخرى" — إظهار مربع نص عند الاختيار
  --------------------------------------------------------- */
  document.querySelectorAll('.nationality-select').forEach(function (sel) {
    var wrap = sel.closest('.nationality-field');
    var other = wrap ? wrap.querySelector('.nationality-other') : null;
    if (!other) return;
    sel.addEventListener('change', function () {
      if (sel.value === 'other') {
        other.style.display = 'block';
        other.focus();
      } else {
        other.style.display = 'none';
        other.value = '';
      }
      resolvePrintTargets(document);
    });
    // عند الكتابة داخل حقل "أخرى" حدّث النسخة المطبوعة أيضًا
    other.addEventListener('input', function () { resolvePrintTargets(document); });
  });

  /* ---------------------------------------------------------
     3) تنسيق التاريخ / الوقت بالشكل العربي عند الطباعة
  --------------------------------------------------------- */
  function formatDateForPrint(iso) {
    if (!iso) return '';
    var parts = iso.split('-');
    if (parts.length !== 3) return '';
    var y = parts[0], m = parts[1], d = parts[2];
    return d + '/' + m + '/' + y + 'م';
  }

  function formatTimeForPrint(t) {
    if (!t) return '';
    var parts = t.split(':');
    if (parts.length < 2) return '';
    var h = parseInt(parts[0], 10);
    var m = parts[1];
    var period = h >= 12 ? 'مساءً' : 'صباحاً';
    var h12 = h % 12;
    if (h12 === 0) h12 = 12;
    return String(h12).padStart(2, '0') + ':' + m + ' ' + period;
  }

  function resolveNationalityValue(selectEl) {
    if (selectEl.value === 'other') {
      var wrap = selectEl.closest('.nationality-field');
      var other = wrap ? wrap.querySelector('.nationality-other') : null;
      return other ? other.value.trim() : '';
    }
    return selectEl.value;
  }

  // يملأ كل عناصر <span class="print-only"> بالقيمة النهائية المنسّقة
  // مباشرة قبل الطباعة، حتى تظهر التواريخ والجنسية "أخرى" بشكل صحيح على الورق
  function resolvePrintTargets(scopeEl) {
    var root = scopeEl || document;
    root.querySelectorAll('[data-print-target]').forEach(function (el) {
      var target = document.getElementById(el.dataset.printTarget);
      if (!target) return;
      var value = '';
      if (el.classList.contains('date-input')) {
        value = formatDateForPrint(el.value);
      } else if (el.classList.contains('time-input')) {
        value = formatTimeForPrint(el.value);
      } else if (el.classList.contains('nationality-select')) {
        value = resolveNationalityValue(el);
      } else {
        value = el.value;
      }
      target.textContent = value;
    });
  }

  window.addEventListener('beforeprint', function () { resolvePrintTargets(document); });

  // أيضًا: حدّث القيم المخصّصة للطباعة عند كل تغيير في الحقل ذاته أو حقل "أخرى"
  // حتى تكون النسخة المطبوعة جاهزة دائمًا حتى لو ضغط المستخدم Ctrl+P مباشرة
  document.querySelectorAll('[data-print-target]').forEach(function (el) {
    el.addEventListener('change', function () { resolvePrintTargets(document); });
    el.addEventListener('input', function () { resolvePrintTargets(document); });
  });
  // شغّل التحديث مرة واحدة عند التحميل لضبط الحالة الابتدائية
  resolvePrintTargets(document);

  /* ---------------------------------------------------------
     4) وضع "المعاينة" — إخفاء عناصر التحكم لرؤية شكل المستند
  --------------------------------------------------------- */
  var btnPreview = document.getElementById('btnPreview');
  var btnClosePreview = document.getElementById('btnClosePreview');

  function togglePreview() {
    resolvePrintTargets(document);
    document.body.classList.toggle('preview-mode');
    if (document.body.classList.contains('preview-mode')) {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }
  if (btnPreview) btnPreview.addEventListener('click', togglePreview);
  if (btnClosePreview) btnClosePreview.addEventListener('click', togglePreview);

  /* ---------------------------------------------------------
     5) طباعة / حفظ PDF (عبر خاصية الطباعة في المتصفح)
  --------------------------------------------------------- */
  var btnPrint = document.getElementById('btnPrint');
  if (btnPrint) {
    btnPrint.addEventListener('click', function () {
      resolvePrintTargets(document);
      window.print();
    });
  }

  /* ---------------------------------------------------------
     6) مسح النموذج النشط حاليًا فقط
  --------------------------------------------------------- */
  var btnClear = document.getElementById('btnClear');
  if (btnClear) {
    btnClear.addEventListener('click', function () {
      var active = document.querySelector('.form-section.active');
      if (!active) return;
      var ok = window.confirm('هل أنت متأكد من مسح جميع البيانات المدخلة في هذا النموذج؟ لا يمكن التراجع عن هذا الإجراء.');
      if (!ok) return;

      active.querySelectorAll('input[type=text], input[type=tel], input[type=date], input[type=time], input[type=number], textarea').forEach(function (el) {
        el.value = '';
      });
      active.querySelectorAll('input[type=checkbox]').forEach(function (el) { el.checked = false; });
      active.querySelectorAll('select').forEach(function (el) { el.selectedIndex = 0; });
      active.querySelectorAll('.nationality-other').forEach(function (el) {
        el.style.display = 'none';
        el.value = '';
      });
      active.querySelectorAll('.print-only').forEach(function (el) { el.textContent = ''; });
      active.querySelectorAll('.num-msg').forEach(function (el) { el.textContent = ''; el.className = 'num-msg no-print'; });
      active.querySelectorAll('.num10').forEach(function (el) { el.classList.remove('num-invalid', 'num-ok'); });
      active.querySelectorAll('.party-type-select').forEach(function (el) { el.selectedIndex = 0; syncPartyReveal(el); });
      applyDefaultDates(active);
      showToast('تم مسح النموذج');
    });
  }

  /* ---------------------------------------------------------
     7) نسخ بيانات النموذج كنص منسّق إلى الحافظة
  --------------------------------------------------------- */
  function getDisplayValue(input) {
    if (input.classList.contains('date-input')) return formatDateForPrint(input.value);
    if (input.classList.contains('time-input')) return formatTimeForPrint(input.value);
    if (input.classList.contains('nationality-select')) return resolveNationalityValue(input);
    if (input.tagName === 'SELECT') {
      var opt = input.options[input.selectedIndex];
      return opt ? opt.text : '';
    }
    if (input.type === 'checkbox') return input.checked ? 'نعم' : '—';
    return input.value || '';
  }

  // نص التسمية نظيفًا بدون وسم "اختياري" (يُستخدم عند النسخ والتصدير)
  function cleanLabelText(label) {
    var clone = label.cloneNode(true);
    clone.querySelectorAll('.opt-tag').forEach(function (t) { t.remove(); });
    return clone.textContent.trim();
  }

  // هل هذا الحقل مخفي حاليًا بسبب نظام "نوع الطرف"؟
  function isHiddenPartyField(f) {
    return f.classList.contains('party-reveal') && f.style.display === 'none';
  }

  var btnCopy = document.getElementById('btnCopy');
  if (btnCopy) {
    btnCopy.addEventListener('click', function () {
      var active = document.querySelector('.form-section.active');
      if (!active) return;
      resolvePrintTargets(active);

      var titleEl = active.querySelector('.doc-title');
      var lines = [titleEl ? titleEl.textContent.trim() : '', ''];

      active.querySelectorAll('.doc-section, .signatures').forEach(function (section) {
        var heading = section.querySelector('h2') || section.querySelector('h3.sub-title');
        if (heading) lines.push('# ' + heading.textContent.trim());
        section.querySelectorAll('.field').forEach(function (f) {
          if (isHiddenPartyField(f)) return;
          var label = f.querySelector('label');
          var input = f.querySelector(':scope > input, :scope > select, :scope > textarea');
          if (!label || !input) return;
          lines.push(cleanLabelText(label) + ': ' + getDisplayValue(input));
        });
        section.querySelectorAll('.checkbox-line').forEach(function (cl) {
          var cb = cl.querySelector('.real-checkbox');
          var txtEl = cl.querySelector('.label-text');
          var txt = txtEl ? txtEl.textContent.trim() : cl.textContent.trim();
          lines.push((cb && cb.checked ? '☑' : '☐') + ' ' + txt);
        });
        lines.push('');
      });

      var text = lines.join('\n');
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
          showToast('تم نسخ بيانات النموذج إلى الحافظة');
        }).catch(function () {
          showToast('تعذّر النسخ التلقائي — الرجاء التحديد والنسخ يدويًا');
        });
      } else {
        showToast('المتصفح لا يدعم النسخ التلقائي');
      }
    });
  }

  /* ---------------------------------------------------------
     8) رسالة تأكيد سريعة (Toast)
  --------------------------------------------------------- */
  var toastTimer;
  function showToast(msg) {
    var toast = document.getElementById('toast');
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { toast.classList.remove('show'); }, 2600);
  }

  /* ---------------------------------------------------------
     9) تحميل نسخة Word قابلة للتعديل (.doc)
     ملاحظة: يتم بناء نسخة مبسّطة بجداول (متوافقة مع Word) تحتوي
     كل البيانات المدخلة، لتسهيل التعديل لاحقًا داخل Word.
  --------------------------------------------------------- */
  var LOGO_BLUE_B64 = '';
  var STAMP_B64 = '';

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function buildWordHtml(sectionEl, title) {
    var body = '';
    body += '<div style="text-align:center;margin-bottom:8px;">';
    body += '<img src="data:image/png;base64,' + LOGO_BLUE_B64 + '" style="height:56px;">';
    body += '</div>';
    body += '<h1 style="text-align:center;font-size:16pt;color:#14335c;border:1.5px solid #14335c;' +
      'padding:8px;background:#e9eef6;font-family:Arial,Tahoma,sans-serif;">' + esc(title) + '</h1>';
    body += '<table style="width:100%;border-collapse:collapse;font-size:11pt;font-family:Arial,Tahoma,sans-serif;" dir="rtl">';

    sectionEl.querySelectorAll('.doc-section, .signatures').forEach(function (section) {
      var heading = section.querySelector('h2');
      var headingText = heading ? heading.textContent.trim() : (section.classList.contains('signatures') ? 'التوقيعات' : '');
      if (headingText) {
        body += '<tr><td colspan="2" style="background:#14335c;color:#fff;padding:7px 10px;font-weight:bold;font-size:12pt;">' + esc(headingText) + '</td></tr>';
      }
      section.querySelectorAll('.static-text').forEach(function (st) {
        body += '<tr><td colspan="2" style="padding:6px 10px;border:1px solid #ccc;background:#f7f8fa;">' + esc(st.textContent.trim()) + '</td></tr>';
      });
      // sub-titles (بيانات الطرف الأول/الثاني) كصف عنوان فرعي
      section.querySelectorAll('.sig-block').forEach(function (block) {
        var sub = block.querySelector('.sub-title');
        if (sub) body += '<tr><td colspan="2" style="padding:6px 10px;border:1px solid #ccc;background:#fbf3e2;font-weight:bold;">' + esc(sub.textContent.trim()) + '</td></tr>';
        block.querySelectorAll('.field').forEach(function (f) {
          if (isHiddenPartyField(f)) return;
          var label = f.querySelector('label');
          var input = f.querySelector(':scope > input, :scope > select, :scope > textarea');
          if (!label || !input) return;
          var val = getDisplayValue(input) || '..........................';
          body += '<tr><td style="width:34%;padding:6px 10px;border:1px solid #ccc;font-weight:bold;background:#fafbfc;">' + esc(cleanLabelText(label)) + '</td>' +
            '<td style="padding:6px 10px;border:1px solid #ccc;">' + esc(val) + '</td></tr>';
        });
      });
      // حقول مباشرة (غير داخل sig-block)
      var directFields = section.querySelectorAll(':scope > .grid-2 > .field, :scope > .grid-3 > .field, :scope > .field');
      directFields.forEach(function (f) {
        var label = f.querySelector('label');
        var input = f.querySelector(':scope > input, :scope > select, :scope > textarea');
        if (!label || !input) return;
        var val = getDisplayValue(input) || '..........................';
        body += '<tr><td style="width:34%;padding:6px 10px;border:1px solid #ccc;font-weight:bold;background:#fafbfc;">' + esc(label.textContent.trim()) + '</td>' +
          '<td style="padding:6px 10px;border:1px solid #ccc;">' + esc(val) + '</td></tr>';
      });
      section.querySelectorAll('.checkbox-line').forEach(function (cl) {
        var cb = cl.querySelector('.real-checkbox');
        var txtEl = cl.querySelector('.label-text');
        var txt = txtEl ? txtEl.textContent.trim() : cl.textContent.trim();
        body += '<tr><td colspan="2" style="padding:5px 10px;border:1px solid #ccc;">' + (cb && cb.checked ? '&#9745;' : '&#9744;') + ' ' + esc(txt) + '</td></tr>';
      });
    });

    body += '</table>';
    body += '<div style="margin-top:16px;text-align:center;background:#14335c;color:#fff;padding:8px;font-size:9.5pt;font-family:Arial,Tahoma,sans-serif;">' +
      'الدوادمي - حي السلام - شارع الملك عبدالعزيز &nbsp;|&nbsp; 0116442444 &nbsp;|&nbsp; 0555113181 &nbsp;|&nbsp; ص.ب: 3529 &nbsp;|&nbsp; الرمز: 13121<br>' +
      'Dawadmi - Alslam - King Abdulaziz Street &nbsp;|&nbsp; P.o.Box: 3529 &nbsp;|&nbsp; C: 13121 &nbsp;|&nbsp; www.alserhan.com' +
      '</div>';

    return '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">' +
      '<head><meta charset="utf-8"><title>' + esc(title) + '</title></head>' +
      '<body style="direction:rtl;font-family:Arial,Tahoma,sans-serif;">' + body + '</body></html>';
  }

  var btnWord = document.getElementById('btnWord');
  if (btnWord) {
    btnWord.addEventListener('click', function () {
      var active = document.querySelector('.form-section.active');
      if (!active) return;
      resolvePrintTargets(active);
      var titleEl = active.querySelector('.doc-title');
      var title = titleEl ? titleEl.textContent.trim() : 'سند';
      var html = buildWordHtml(active, title);
      var blob = new Blob(['\ufeff', html], { type: 'application/msword' });
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url;
      var safeName = title.replace(/[^\u0621-\u064Aa-zA-Z0-9 ]/g, '').trim() || 'سند';
      a.download = safeName + '.doc';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(function () { URL.revokeObjectURL(url); }, 4000);
      showToast('جارٍ تحميل ملف Word');
    });
  }


  /* ---------------------------------------------------------
     10) نظام "نوع الطرف" (موظف / مندوب / شركة) — يعمل عمومًا على
     أي select بصنف party-type-select مرتبط بمجموعة حقول .party-reveal
     عبر data-reveal-for / data-reveal-when
  --------------------------------------------------------- */
  function syncPartyReveal(sel) {
    var group = sel.dataset.revealGroup;
    if (!group) return;
    document.querySelectorAll('.party-reveal[data-reveal-for="' + group + '"]').forEach(function (r) {
      var show = r.dataset.revealWhen === sel.value;
      r.style.display = show ? 'flex' : 'none';
      if (!show) {
        var inp = r.querySelector('input, select, textarea');
        if (inp && inp.value) inp.value = '';
      }
    });
  }
  document.querySelectorAll('.party-type-select').forEach(function (sel) {
    sel.addEventListener('change', function () { syncPartyReveal(sel); });
    syncPartyReveal(sel);
  });

  /* ---------------------------------------------------------
     11) حقول الأرقام: 10 خانات بالضبط (الهوية / الإقامة / الجوال)
     - تقبل أرقامًا فقط (وتحوّل الأرقام العربية تلقائيًا)
     - تتوقف عند الرقم العاشر وتنبّه المستخدم عند محاولة الزيادة
  --------------------------------------------------------- */
  var AR_DIGITS = /[\u0660-\u0669\u06F0-\u06F9]/g;
  function toWesternDigits(s) {
    return String(s).replace(AR_DIGITS, function (d) {
      var c = d.charCodeAt(0);
      return String(c >= 0x06F0 ? c - 0x06F0 : c - 0x0660);
    });
  }

  function numFieldMessage(el, msgEl) {
    var v = el.value;
    var kind = el.dataset.kind || 'id';
    el.classList.remove('num-invalid', 'num-ok');
    msgEl.className = 'num-msg no-print';

    if (v.length === 0) { msgEl.textContent = ''; return; }

    if (v.length < 10) {
      msgEl.textContent = '🛑 ناقص ' + (10 - v.length) + ' — لازم 10 أرقام (' + v.length + '/10)';
      msgEl.classList.add('bad');
      if (document.activeElement !== el) el.classList.add('num-invalid');
      return;
    }

    // اكتملت 10 أرقام — تحقق شكلي إضافي (تنبيه فقط، لا يمنع الطباعة)
    if (kind === 'phone' && v.slice(0, 2) !== '05') {
      msgEl.textContent = '⚠️ تأكد: رقم الجوال السعودي يبدأ بـ 05';
      msgEl.classList.add('warn');
      return;
    }
    if (kind === 'id' && v[0] !== '1' && v[0] !== '2') {
      msgEl.textContent = '⚠️ تأكد: رقم الهوية/الإقامة يبدأ بـ 1 أو 2';
      msgEl.classList.add('warn');
      return;
    }
    msgEl.textContent = '✓ 10/10';
    msgEl.classList.add('ok');
    el.classList.add('num-ok');
  }

  var overTimer;
  document.querySelectorAll('.num10').forEach(function (el) {
    var host = el.closest('.field') || el.parentNode;
    var msgEl = document.createElement('span');
    msgEl.className = 'num-msg no-print';
    msgEl.setAttribute('aria-live', 'polite');
    host.appendChild(msgEl);

    el.setAttribute('maxlength', '10');

    el.addEventListener('input', function () {
      var raw = toWesternDigits(el.value);
      var clean = raw.replace(/\D/g, '');
      var overflow = clean.length > 10;
      if (overflow) clean = clean.slice(0, 10);

      if (clean !== el.value) {
        var pos = el.selectionStart;
        el.value = clean;
        try { el.setSelectionRange(pos, pos); } catch (e) {}
      }

      if (overflow) {
        el.classList.add('num-over');
        clearTimeout(overTimer);
        overTimer = setTimeout(function () { el.classList.remove('num-over'); }, 400);
        showToast('🛑 الحقل يقبل 10 أرقام فقط');
      }
      numFieldMessage(el, msgEl);
    });

    el.addEventListener('blur', function () { numFieldMessage(el, msgEl); });
    el.addEventListener('paste', function () {
      setTimeout(function () { el.dispatchEvent(new Event('input')); }, 0);
    });
    numFieldMessage(el, msgEl);
  });

  /* ---------------------------------------------------------
     12) تعبئة تاريخ اليوم افتراضيًا في الحقول المخصصة لذلك فقط
  --------------------------------------------------------- */
  function applyDefaultDates(scopeEl) {
    var root = scopeEl || document;
    var today = new Date();
    var iso = today.getFullYear() + '-' + String(today.getMonth() + 1).padStart(2, '0') + '-' + String(today.getDate()).padStart(2, '0');
    root.querySelectorAll('input.date-input[data-default-today]').forEach(function (el) {
      if (!el.value) el.value = iso;
    });
  }
  applyDefaultDates(document);

})();
